import{_ as t,a,c as s,ac as l}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · Lesson 100 He says that ...","description":"学习 现在时引述与宾语从句，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 100 He says that ...","description":"学习 现在时引述与宾语从句，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 现在时引述与宾语从句，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 99 Ow!","link":"/life/english/new-concept/book-1/unit-05/lesson-099"},"next":{"text":"第一册：英语初阶 · Lesson 101 A card from Jimmy","link":"/life/english/new-concept/book-1/unit-05/lesson-101"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 99 Ow!","link":"/life/english/new-concept/book-1/unit-05/lesson-099"},"next":{"text":"第一册：英语初阶 · Lesson 101 A card from Jimmy","link":"/life/english/new-concept/book-1/unit-05/lesson-101"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-05/lesson-100.md","filePath":"life/english/new-concept/book-1/unit-05/lesson-100.md"}'),n={name:"life/english/new-concept/book-1/unit-05/lesson-100.md"};function o(i,e,r,h,d,c){return a(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="第一册-英语初阶-·-lesson-100-he-says-that" tabindex="-1">第一册：英语初阶 · Lesson 100 He says that ... <a class="header-anchor" href="#第一册-英语初阶-·-lesson-100-he-says-that" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 100 He says that ...&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元 5</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-099">配套课 Lesson 99</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>转述别人正在说的内容 本课要掌握现在时引述与宾语从句，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>hurt</td><td>/hɜːt/</td><td>v.</td><td>疼痛；伤害</td><td>my arm hurts</td></tr><tr><td>slip</td><td>/slɪp/</td><td>v.</td><td>滑倒</td><td>slip on ice</td></tr><tr><td>back</td><td>/bæk/</td><td>n.</td><td>背部</td><td>hurt one&#39;s back</td></tr><tr><td>say</td><td>/seɪ/</td><td>v.</td><td>说</td><td>say that</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>says that — 引出转述内容</li><li>tells me that — tell 后接听话的人</li></ul><h2 id="语法讲解-现在时引述与宾语从句" tabindex="-1">语法讲解：现在时引述与宾语从句 <a class="header-anchor" href="#语法讲解-现在时引述与宾语从句" aria-label="Permalink to &quot;语法讲解：现在时引述与宾语从句&quot;">​</a></h2><p>say 后可以接 that 引导的内容从句，that 在口语中常省略。主句为一般现在时 says 时，从句根据实际时间选择时态，不自动变过去。tell 通常需要人作宾语，如 tells me that ...；say 不能直接接人作宾语说 say me。宾语从句内部保留陈述语序，即使它含疑问意义也不能随意倒装。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>She tells me that the floor is wet.</p></blockquote><p>她告诉我地板是湿的。</p><p>Tells 后接 me 表听话人，再接 that 从句；the floor is wet 使用完整陈述语序。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>say me 应改为 tell me 或 say to me；不要把 say 与 tell 的宾语结构混用。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“She tells me that the floor is wet.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>She tells me that the floor is wet. Ben says that his ankle hurts.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“转述别人正在说的内容”写两至三句，再读给同伴听。至少使用一次现在时引述与宾语从句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Tells 后接 me 表听话人，再接 that 从句；the floor is wet 使用完整陈述语序。 Ben says 是主句，that his ankle hurts 是宾语从句；ankle 单数，所以从句谓语 hurt 加 s。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选择 says/tells：She ___ me that the floor is wet.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> tells</p><p><strong>解析：</strong> 按本课规则判断：say 后可以接 that 引导的内容从句，that 在口语中常省略。主句为一般现在时 says 时，从句根据实际时间选择时态，不自动变过去。tell 通常需要人作宾语，如 tells me that ...；say 不能直接接人作宾语说 say me。宾语从句内部保留陈述语序，即使它含疑问意义也不能随意倒装。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“她告诉我地板是湿的。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She tells me that the floor is wet.</p><p><strong>解析：</strong> Tells 后接 me 表听话人，再接 that 从句；the floor is wet 使用完整陈述语序。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：Ben says that his ankle hurts.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 本说他的脚踝疼。</p><p><strong>解析：</strong> Ben says 是主句，that his ankle hurts 是宾语从句；ankle 单数，所以从句谓语 hurt 加 s。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：现在时引述与宾语从句。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-05/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-05/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-05/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-099">上一课</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-101">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
